<style>
    .desktop-simple-header {
        display: none;
    }

    @media (min-width: 768px) {
        .desktop-simple-header {
            display: block;
        }
    }

    ul {
        list-style: none;
    }

    a {
        text-decoration: none;
    }

    /* Overhead Bar */
    .overhead {
        background-color: #f0f0f0;
        color: #333;
        padding: 10px 0;
        font-size: 12px;
    }

    .overhead .container {
        max-width: 1400px;
        margin: 0 auto;
        display: flex;
        justify-content: space-between;
        align-items: center;
        padding: 0 40px;
    }

    .overhead .social-icons a {
        margin-left: 15px;
        color: #555;
    }

    /* Header Section */
    header {
        background-color: #fff;
        padding: 30px 0;
    }

    .header-container {
        max-width: 1400px;
        margin: 0 auto;
        display: flex;
        justify-content: space-between;
        align-items: center;
        padding: 0 40px;
    }

    .logo {
        font-size: 18px;
        /* Reduced font size for the logo text */
        font-weight: bold;
    }

    .logo img {
        height: 60px;
    }

    /* Navbar */
    .navbar {
        background: linear-gradient(135deg, #1a1a1a, #2b2b2b);
        color: white;
        box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
        /* Subtle shadow for depth */
    }

    .navbar .container {
        max-width: 1400px;
        margin: 0 auto;
        padding: 0 40px;
    }

    .navbar ul {
        display: flex;
        justify-content: flex-start;
        padding: 20px 0;
        border-bottom: 1px solid rgba(255, 255, 255, 0.1);
        /* Subtle bottom line for structure */
    }

    .navbar ul li {
        margin-right: 30px;
        position: relative;
    }

    .navbar ul li:not(:last-child)::after {
        content: "|";
        color: rgba(255, 255, 255, 0.2);
        /* Divider between menu items */
        margin-left: 20px;
    }

    .navbar ul li a {
        color: white;
        font-size: 18px;
        padding: 10px;
        transition: color 0.3s, border-bottom 0.3s;
    }

    .navbar ul li a:hover {
        color: #ffcc00;
        /* Professional gold accent */
        border-bottom: 2px solid #ffcc00;
        /* Underline effect on hover */
    }

    /* .navbar ul li a.active {
        border-bottom: 3px solid #007BFF;
    } */

    .navbar ul li a[aria-current="page"] {
        border-bottom: 3px solid #007BFF;
    }
</style>

