    .mobile-header-container {
        display: none;
    }

    /* Mobile Header */
    .mobile-header-container .mobile-header {
        display: flex;
        justify-content: space-between;
        align-items: center;
        padding: 0 15px;
        position: fixed;
        top: 0;
        width: 100%;
        background-color: rgba(255, 255, 255, 1);
        box-shadow: 0px 2px 5px rgba(0, 0, 0, 0.1);
        z-index: 1000;
        border-bottom: 1px solid #ddd;
        box-sizing: border-box;
    }

    .mobile-header-container .mobile-header .logo h1 {
        Font-size:26px;
    }

    /* Hamburger and Close button */
    .mobile-header-container .mobile-header .hamburger-menu,
    .mobile-header-container .mobile-header .close-menu {
        font-size: 32px;
        /* Slightly larger for better visibility */
        cursor: pointer;
        color: #333;
        position: absolute;
        right: 25px;
        top: 9px;
        transition: transform 0.3s ease;
    }

    /* Initially hide the close button */
    .mobile-header-container .mobile-header .close-menu {
        display: none;
    }

    /* Overlay */
    .mobile-header-container .mobile-menu-overlay {
        position: fixed;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background-color: rgba(0, 0, 0, 0.5);
        opacity: 0;
        visibility: hidden;
        transition: opacity 0.3s ease, visibility 0.3s ease;
        z-index: 999;
    }

    .mobile-header-container .mobile-menu-overlay.open {
        opacity: 1;
        visibility: visible;
    }

    /* Slide-out Menu */
    .mobile-header-container .mobile-menu {
        position: fixed;
        top: 0;
        left: -100%;
        width: 80%;
        height: 100%;
        background-color: white;
        overflow-y: auto;
        z-index: 1000;
        box-shadow: 2px 0 10px rgba(0, 0, 0, 0.1);
        transition: left 0.3s ease-in-out;
    }

    .mobile-header-container .mobile-menu.open {
        left: 0;
    }

    /* Styling Menu Items */
    .mobile-header-container .mobile-menu .mobile-menu-list {
        list-style: none;
        padding: 20px;
        margin: 0;
    }

    .mobile-header-container .mobile-menu .mobile-menu-list>li {
        margin-bottom: 0;
        border-bottom: 1px solid #ddd;
        /* Subtle line separator */
        padding-bottom: 0;
    }

    .mobile-header-container .mobile-menu .mobile-menu-list>li>a {
        text-decoration: none;
        font-size: 20px;
        color: #262626;
        padding: 8px 0;
        display: block;
        background-color: transparent;
        transition: background-color 0.3s ease, padding-left 0.3s ease;
    }

    .mobile-header-container .mobile-menu .mobile-menu-list>li>a:hover {
        background-color: #f1f1f1;
        padding-left: 12px;
    }

    /* Styling for Submenu */
    .mobile-header-container .mobile-menu .submenu {
        list-style: none;
        padding-left: 20px;
        margin-top: 0;
        margin-bottom: 0;
    }

    .mobile-header-container .mobile-menu .submenu>li {
        border-bottom: 1px solid #eee;
        padding-bottom: 0;
        margin-bottom: 0;
    }

    .mobile-header-container .mobile-menu .submenu>li>a {
        text-decoration: none;
        font-size: 16px;
        /* Smaller font for submenu items */
        color: #666;
        /* Lighter color for submenu text */
        padding: 5px 0;
        /* Padding around submenu text */
        display: block;
        transition: background-color 0.3s ease, padding-left 0.3s ease;
    }

    .mobile-header-container .mobile-menu .submenu>li>a:hover {
        background-color: #f9f9f9;
        /* Light background on hover */
        padding-left: 12px;
        /* Slightly increased left padding on hover */
    }

    /* Hide Hamburger, Show Close Button when menu is open */
    .mobile-header-container .mobile-header .hamburger-menu.open {
        display: none;
    }

    .mobile-header-container .mobile-header .close-menu.open {
        display: block;
    }

    /* Hide the hamburger icon on desktop */
    @media (max-width: 769px) {
        .mobile-header-container {
            display: block;
        }
    }
</style>


