<script>
    document.addEventListener("DOMContentLoaded", function () {
        const hamburger = document.getElementById("mobileHeaderHamburger");
        const mobileMenu = document.getElementById("mobileHeaderMenu");
        const closeButton = document.getElementById("mobileHeaderCloseButton");
        const menuOverlay = document.getElementById("mobileHeaderOverlay");

        // Open Menu
        hamburger.addEventListener("click", function () {
            mobileMenu.classList.add("open");
            menuOverlay.classList.add("open");
            hamburger.classList.add("open");
            closeButton.classList.add("open");
        });

        // Close Menu
        closeButton.addEventListener("click", function () {
            mobileMenu.classList.remove("open");
            menuOverlay.classList.remove("open");
            hamburger.classList.remove("open");
            closeButton.classList.remove("open");
        });

        // Close Menu when clicking overlay
        menuOverlay.addEventListener("click", function () {
            mobileMenu.classList.remove("open");
            menuOverlay.classList.remove("open");
            hamburger.classList.remove("open");
            closeButton.classList.remove("open");
        });
    });

</script>
    <div class="content">
